(()=>{'use strict';const A=[...document.querySelectorAll('.exercise')],K='navidad-v2',w=(m,e)=>console.warn('[navidad] '+m,e||''),get=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch(e){w('storage',e);return{}}},save=()=>{try{localStorage.setItem(K,JSON.stringify(Object.fromEntries(A.map(x=>[x.id,{v:x.querySelector('textarea')?.value||'',d:!!x.querySelector('[data-check]')?.checked}]))))}catch(e){w('storage',e)}},draw=()=>{for(const l of['apoyo','consolidacion','profundizacion','desafio']){let x=A.filter(a=>a.dataset.level===l),n=x.filter(a=>a.querySelector('[data-check]')?.checked).length,b=document.querySelector('#bar-'+l),t=document.querySelector('#txt-'+l);if(b)b.style.width=25*n+'%';if(t)t.textContent=n+'/4'}};let d=get();A.forEach(x=>{let o=d[x.id]||{},t=x.querySelector('textarea'),c=x.querySelector('[data-check]');if(t)t.value=o.v||'';if(c)c.checked=!!o.d});document.addEventListener('input',e=>{if(e.target.matches('textarea'))save()});document.addEventListener('change',e=>{if(e.target.matches('[data-check]'))save(),draw()});document.addEventListener('click',e=>{if(e.target.closest('[data-action=top]'))scrollTo({top:0,behavior:'smooth'})});addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));draw();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./navidad-sw.js').catch(e=>w('cache',e)),{once:true})})();